import java.util.*;

public class Main {
    static final int CAP = 16;                          // capacity is a power of two
    static List<List<int[]>> table = new ArrayList<>(); // each bucket: list of {hash, key, value}

    static int spread(int h) { return h ^ (h >>> 16); } // mix the high bits into the low bits

    static void put(int key, int value) {
        int h = spread(key);
        table.get(h & (CAP - 1)).add(new int[]{h, key, value}); // index = hash AND (capacity - 1)
    }

    static void get(int key) {
        int h = spread(key), i = h & (CAP - 1), checked = 0;
        for (int[] e : table.get(i)) {                  // walk the chain in that one bucket
            checked++;
            if (e[0] == h && e[1] == key) {             // compare stored hash first, then the key
                System.out.println("get(" + key + "): bucket " + i + ", checked " + checked + " entries, value " + e[2]);
                return;
            }
        }
        System.out.println("get(" + key + "): bucket " + i + ", checked " + checked + " entries, not found");
    }

    // Time: O(1) average per get/put, O(chain length) in one bucket. Space: O(N).
    public static void main(String[] args) {
        for (int i = 0; i < CAP; i++) table.add(new ArrayList<>());
        int[] keys = {17, 33, 1, 65552};
        System.out.println("keys = " + Arrays.toString(keys) + ", capacity = " + CAP);
        for (int k : keys) put(k, k * 10);
        get(33);
        get(65552);
        get(49);
        get(5);
    }
}

