using System;
using System.Collections.Generic;

class Program {
    const int CAP = 16;                                  // capacity is a power of two
    static List<List<int[]>> table = new List<List<int[]>>(); // each bucket: list of {hash, key, value}

    static int Spread(int h) { return h ^ (int)((uint)h >> 16); } // mix the high bits into the low bits

    static void Put(int key, int value) {
        int h = Spread(key);
        table[h & (CAP - 1)].Add(new int[] { h, key, value }); // index = hash AND (capacity - 1)
    }

    static void Get(int key) {
        int h = Spread(key), i = h & (CAP - 1), check = 0;
        foreach (int[] e in table[i]) {                  // walk the chain in that one bucket
            check++;
            if (e[0] == h && e[1] == key) {              // compare stored hash first, then the key
                Console.WriteLine("get(" + key + "): bucket " + i + ", checked " + check + " entries, value " + e[2]);
                return;
            }
        }
        Console.WriteLine("get(" + key + "): bucket " + i + ", checked " + check + " entries, not found");
    }

    // Time: O(1) average per get/put, O(chain length) in one bucket. Space: O(N).
    static void Main() {
        for (int i = 0; i < CAP; i++) table.Add(new List<int[]>());
        int[] keys = { 17, 33, 1, 65552 };
        Console.WriteLine("keys = [" + string.Join(", ", keys) + "], capacity = " + CAP);
        foreach (int k in keys) Put(k, k * 10);
        Get(33);
        Get(65552);
        Get(49);
        Get(5);
    }
}

