import java.util.*;

public class Main {
    static int nextId = 0;

    // A point is {x, y, id}. The id is different for every object, like a memory address.
    static int[] point(int x, int y) { return new int[]{x, y, ++nextId}; }

    static boolean same(int[] p, int[] q) { return p[0] == q[0] && p[1] == q[1]; } // plays equals()

    static int hash(int[] p, boolean useFields) {
        return useFields ? 31 * p[0] + p[1] : p[2] * 7;  // good hash uses x and y; bad one uses the id
    }

    static void demo(String label, boolean useFields) {
        List<List<int[]>> buckets = new ArrayList<>();
        for (int i = 0; i < 8; i++) buckets.add(new ArrayList<>());
        int[] a = point(1, 2), b = point(1, 2);
        buckets.get(hash(a, useFields) % 8).add(a);            // add(a)
        List<int[]> chain = buckets.get(hash(b, useFields) % 8);
        boolean found = false;
        for (int[] p : chain) if (same(p, b)) found = true;    // contains(b) searches b's bucket only
        if (!found) chain.add(b);                              // add(b) stores a "duplicate"
        int size = 0;
        for (List<int[]> c : buckets) size += c.size();
        System.out.println(label + ": contains(b) = " + (found ? "yes" : "no") + ", size after add(b) = " + size);
    }

    // Time: O(1) average per add/contains. Space: O(N).
    public static void main(String[] args) {
        System.out.println("a = (1, 2), b = (1, 2), a equals b: yes");
        demo("hash ignores the fields", false);
        demo("hash uses the fields", true);
    }
}

