class Program {
    static int nextId = 0;

    // A point is {x, y, id}. The id is different for every object, like a memory address.
    static int[] Point(int x, int y) { return new int[] { x, y, ++nextId }; }

    static bool Same(int[] p, int[] q) { return p[0] == q[0] && p[1] == q[1]; } // plays Equals()

    static int Hash(int[] p, bool useFields) {
        return useFields ? 31 * p[0] + p[1] : p[2] * 7;  // good hash uses x and y; bad one uses the id
    }

    static void Demo(string label, bool useFields) {
        List<List<int[]>> buckets = new List<List<int[]>>();
        for (int i = 0; i < 8; i++) buckets.Add(new List<int[]>());
        int[] a = Point(1, 2), b = Point(1, 2);
        buckets[Hash(a, useFields) % 8].Add(a);              // add(a)
        List<int[]> chain = buckets[Hash(b, useFields) % 8];
        bool found = false;
        foreach (int[] p in chain) if (Same(p, b)) found = true; // contains(b) searches b's bucket only
        if (!found) chain.Add(b);                            // add(b) stores a "duplicate"
        int size = 0;
        foreach (List<int[]> c in buckets) size += c.Count;
        Console.WriteLine(label + ": contains(b) = " + (found ? "yes" : "no") + ", size after add(b) = " + size);
    }

    // Time: O(1) average per add/contains. Space: O(N).
    static void Main() {
        Console.WriteLine("a = (1, 2), b = (1, 2), a equals b: yes");
        Demo("hash ignores the fields", false);
        Demo("hash uses the fields", true);
    }
}

