import java.util.*;

public class Main {
    static final int N = 1000, CAP = 1024;

    // Insert keys 0..N-1, then look every key up and count key comparisons.
    static long comparisons(boolean allCollide) {
        List<List<Integer>> buckets = new ArrayList<>();
        for (int i = 0; i < CAP; i++) buckets.add(new ArrayList<>());
        for (int key = 0; key < N; key++) {
            int index = allCollide ? 0 : key & (CAP - 1);   // a bad hash sends everything to bucket 0
            buckets.get(index).add(key);
        }
        long count = 0;
        for (int key = 0; key < N; key++) {
            int index = allCollide ? 0 : key & (CAP - 1);
            for (int stored : buckets.get(index)) {         // walk the chain until the key is found
                count++;
                if (stored == key) break;
            }
        }
        return count;
    }

    // Good hash: O(1) per lookup, O(N) in total. All colliding: O(N) per lookup, O(N^2) in total.
    // Space: O(N + capacity).
    public static void main(String[] args) {
        System.out.println("N = " + N + " keys, " + CAP + " buckets");
        System.out.println("good hash: " + comparisons(false) + " comparisons for " + N + " lookups");
        System.out.println("all keys collide: " + comparisons(true) + " comparisons for " + N + " lookups");
    }
}

