import java.util.*;

public class Main {
    // Time: O(N) to move N keys during one resize. Space: O(new capacity).
    public static void main(String[] args) {
        int oldCap = 8, newCap = 16;
        int[] keys = {3, 11, 19, 27, 5, 13};
        int threshold = oldCap * 3 / 4;              // load factor 0.75: grow when size > 6
        System.out.println("keys = " + Arrays.toString(keys));
        System.out.println("capacity " + oldCap + ", grows when size > " + threshold);
        int stayed = 0, moved = 0;
        for (int key : keys) {
            int oldIndex = key & (oldCap - 1);       // uses the low 3 bits of the hash
            int newIndex = key & (newCap - 1);       // uses the low 4 bits: one extra bit
            boolean moves = (key & oldCap) != 0;     // that extra bit decides: stay or move
            if (moves) moved++; else stayed++;
            System.out.println("key " + key + ": index " + oldIndex + " -> " + newIndex
                + (moves ? " (moves by " + oldCap + ")" : " (stays)"));
        }
        System.out.println("stayed: " + stayed + ", moved: " + moved);
    }
}

