import java.util.*;

public class Main {
    static final int EMPTY = -1, TOMB = -2, SIZE = 8;
    static int[] table = new int[SIZE];

    static void insert(int key) {
        int i = key % SIZE;
        while (table[i] != EMPTY && table[i] != TOMB) i = (i + 1) % SIZE;  // slot taken: try the next one
        table[i] = key;
    }

    static int find(int key) {
        int i = key % SIZE;
        for (int step = 0; step < SIZE; step++) {
            if (table[i] == EMPTY) return -1;       // a truly empty slot ends the search
            if (table[i] == key) return i;
            i = (i + 1) % SIZE;                     // tombstones are skipped, not stopped at
        }
        return -1;
    }

    // Time: O(1) average per operation at low load, O(N) worst case. Space: O(capacity), no nodes.
    public static void main(String[] args) {
        Arrays.fill(table, EMPTY);
        insert(1); insert(9); insert(17);           // all three want slot 1
        System.out.println("after insert 1, 9, 17: " + Arrays.toString(table));
        int slot = find(9);
        table[slot] = TOMB;                         // correct delete: leave a marker
        System.out.println("delete 9 with a tombstone: find(17) = " + find(17));
        table[slot] = EMPTY;                        // wrong delete: breaks the probe chain
        System.out.println("delete 9 by emptying the slot: find(17) = " + find(17));
    }
}

