    static int countSubarrays(int[] arr, int k) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, 1);                              // the empty prefix has sum 0 and occurred once
        int prefix = 0, answer = 0;
        for (int x : arr) {
            prefix += x;
            answer += seen.getOrDefault(prefix - k, 0);  // earlier prefixes that leave exactly k
            seen.merge(prefix, 1, Integer::sum);     // insert after the query, never before
        }
        return answer;
    }

