        int k = 7;
        System.out.println("arr = " + Arrays.toString(arr) + ", K = " + k);
        System.out.println("subarrays with sum " + k + ": " + countSubarrays(arr, k));
        System.out.println("with K = 0: " + countSubarrays(arr, 0));
    }
