import java.util.*;

public class Main {
    // Time: O(N). Space: O(N) for the map prefix sum -> first index.
    static int longest(int[] arr, int k, boolean seed) {
        Map<Integer, Integer> first = new HashMap<>();
        if (seed) first.put(0, -1);                  // the empty prefix sits just before index 0
        int prefix = 0, best = 0;
        for (int i = 0; i < arr.length; i++) {
            prefix += arr[i];
            Integer start = first.get(prefix - k);   // earliest place where the rest sums to k
            if (start != null) best = Math.max(best, i - start);
            first.putIfAbsent(prefix, i);            // keep the earliest index only
        }
        return best;
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 7};
        int k = 6;
        System.out.println("arr = " + Arrays.toString(arr) + ", K = " + k);
        System.out.println("with seed {0: -1}: longest = " + longest(arr, k, true));
        System.out.println("without the seed:  longest = " + longest(arr, k, false));
    }
}

