import java.util.*;

public class Main {
    static List<Integer> values = new ArrayList<>();           // gives O(1) random access
    static Map<Integer, Integer> indexOf = new HashMap<>();    // value -> its index in the list
    static Random random = new Random();

    static boolean insert(int v) {
        if (indexOf.containsKey(v)) return false;
        indexOf.put(v, values.size());
        values.add(v);
        return true;
    }

    static boolean remove(int v) {
        Integer i = indexOf.get(v);
        if (i == null) return false;
        int last = values.get(values.size() - 1);
        values.set(i, last);                 // move the last element into the hole
        indexOf.put(last, i);                // and record its new index
        values.remove(values.size() - 1);    // removing the last item needs no shifting
        indexOf.remove(v);
        return true;
    }

    static int getRandom() { return values.get(random.nextInt(values.size())); }

    // Time: O(1) average for all three operations. Space: O(N).
    public static void main(String[] args) {
        for (int v : new int[]{10, 20, 30, 40}) insert(v);
        System.out.println("after insert 10, 20, 30, 40: " + values);
        remove(20);
        System.out.println("after remove 20: " + values);
        System.out.println("index of 40 in the map: " + indexOf.get(40));
        System.out.println("getRandom returned a current member: " + (indexOf.containsKey(getRandom()) ? "yes" : "no"));
    }
}

