import java.util.*;

public class Main {
    // Two workers each add 1 three times. We replay, on one thread, the order of steps
    // that two real threads can produce, so the result is the same on every run.

    static int unsafeCount() {
        Map<String, Integer> hits = new HashMap<>();
        hits.put("home", 0);
        for (int round = 0; round < 3; round++) {
            int a = hits.get("home");        // worker A reads the count
            int b = hits.get("home");        // worker B reads the same old count
            hits.put("home", a + 1);         // A writes
            hits.put("home", b + 1);         // B overwrites A's update: one increment is lost
        }
        return hits.get("home");
    }

    static int atomicCount() {
        Map<String, Integer> hits = new HashMap<>();
        for (int round = 0; round < 3; round++) {
            hits.merge("home", 1, Integer::sum);   // read + add + write as one step (worker A)
            hits.merge("home", 1, Integer::sum);   // worker B sees A's result
        }
        return hits.get("home");
    }

    // Time: O(1) per update. Space: O(number of keys).
    public static void main(String[] args) {
        int unsafe = unsafeCount();
        System.out.println("6 increments, read and write interleaved: count = " + unsafe + " (" + (6 - unsafe) + " lost)");
        System.out.println("6 increments, each one atomic: count = " + atomicCount());
    }
}

