import java.util.*;

public class Main {
    // Time: O(N) average. Space: O(N) for the set.
    public static void main(String[] args) {
        int[] nums = {100, 4, 200, 1, 3, 2, 2};
        Set<Integer> set = new HashSet<>();
        for (int x : nums) set.add(x);
        int best = 0, innerSteps = 0;
        for (int x : set) {                       // loop over the set, so duplicates are visited once
            if (set.contains(x - 1)) continue;    // x is not the front of a run: skip it
            int length = 1;
            while (set.contains(x + length)) {    // walk the run starting at its front
                length++;
                innerSteps++;
            }
            best = Math.max(best, length);
        }
        System.out.println("nums = " + Arrays.toString(nums));
        System.out.println("longest run of consecutive values: " + best);
        System.out.println("inner loop steps in total: " + innerSteps + " (N = " + nums.length + ")");
    }
}

