        Console.WriteLine("nums = [" + string.Join(", ", nums) + "]");
        Console.WriteLine("longest run of consecutive values: " + best);
        Console.WriteLine("inner loop steps in total: " + innerSteps + " (N = " + nums.Length + ")");
    }
}

