public class Main {
    // Time: O(|s| + |t|), each pointer only moves forward. Space: O(1), a 128-slot table.
    static String minWindow(String s, String t) {
        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++;
        int missing = t.length(), left = 0, bestStart = 0, bestLen = Integer.MAX_VALUE;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (need[c] > 0) missing--;            // this character was still required
            need[c]--;                             // extra copies go negative
            while (missing == 0) {                 // window covers t: record it, then shrink
                if (right - left + 1 < bestLen) { bestLen = right - left + 1; bestStart = left; }
                char d = s.charAt(left++);
                need[d]++;
                if (need[d] > 0) missing++;        // we just dropped a required character
            }
        }
        return bestLen == Integer.MAX_VALUE ? "" : s.substring(bestStart, bestStart + bestLen);
    }

    public static void main(String[] args) {
        String s = "ADOBECODEBANC", t = "ABC";
        String w = minWindow(s, t);
        System.out.println("s = " + s + ", t = " + t);
        System.out.println("smallest window: " + w + " (length " + w.length() + ")");
        System.out.println("t = AABC: " + minWindow(s, "AABC"));
    }
}

