public class Main {
    // Key = the 26 letter counts joined with '#', for example "1#0#0#0#1#...".
    static String keyOf(String word) {
        int[] count = new int[26];
        for (char c : word.toCharArray()) count[c - 'a']++;
        StringBuilder sb = new StringBuilder();
        for (int n : count) sb.append(n).append('#');   // the separator keeps 1,11 apart from 11,1
        return sb.toString();
    }

    // Time: O(N * K) for N words of length K. Space: O(N * K).
    public static void main(String[] args) {
        String[] words = {"eat", "tea", "tan", "ate", "nat", "bat", ""};
        Map<String, List<String>> groups = new LinkedHashMap<>();   // keeps first-seen order
        for (String w : words) {
            groups.computeIfAbsent(keyOf(w), k -> new ArrayList<>()).add(w);  // anagrams share a key
        }
        System.out.println("words: " + String.join(" ", words) + "(last one is the empty string)");
        int number = 1;
        for (List<String> g : groups.values()) {
            System.out.println("group " + number++ + " (" + g.size() + "): [" + String.join(", ", g) + "]");
        }
    }
}

