import java.util.*;

public class Main {
    // Count how many different hash values 100 grid points get from one formula.
    static int distinct(boolean weak) {
        Set<Integer> hashes = new HashSet<>();
        for (int x = 0; x < 10; x++) {
            for (int y = 0; y < 10; y++) {
                int h = weak ? x + y            // (1, 2) and (2, 1) both give 3
                             : 31 * x + y;      // the multiplier makes the position of x matter
                hashes.add(h);
            }
        }
        return hashes.size();
    }

    // Time: O(1) to hash one point. Space: O(1).
    public static void main(String[] args) {
        int total = 100, weak = distinct(true), good = distinct(false);
        System.out.println("100 points with x and y from 0 to 9");
        System.out.println("x + y: " + weak + " distinct hash values, " + (total - weak) + " points collide with an earlier one");
        System.out.println("31 * x + y: " + good + " distinct hash values, " + (total - good) + " points collide with an earlier one");
        System.out.println("(1, 2) and (2, 1) with 31 * x + y: " + (31 * 1 + 2) + " and " + (31 * 2 + 1));
    }
}

