import java.util.*;

public class Main {
    // Time: O(N), each visit is added once and removed once. Space: O(window).
    static List<Integer> uniquePerWindow(int[] visits, int window) {
        Map<Integer, Integer> inWindow = new HashMap<>();   // user id -> visits inside the window
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < visits.length; i++) {
            inWindow.merge(visits[i], 1, Integer::sum);     // the new visit enters
            if (i >= window) {
                int old = visits[i - window];               // the oldest visit leaves
                if (inWindow.merge(old, -1, Integer::sum) == 0) inWindow.remove(old);  // drop keys at 0
            }
            if (i >= window - 1) result.add(inWindow.size());   // map size = unique users
        }
        return result;
    }

    public static void main(String[] args) {
        int[] visits = {7, 7, 8, 7, 9, 9, 9, 9};
        int window = 4;
        System.out.println("visits (user ids) = " + Arrays.toString(visits) + ", window = " + window);
        System.out.println("unique visitors per window: " + uniquePerWindow(visits, window));
    }
}

