// Time: O(N), each visit is added once and removed once. Space: O(window).
vector<int> uniquePerWindow(const vector<int>& visits, int window) {
    unordered_map<int, int> inWindow;            // user id -> visits inside the window
    vector<int> result;
    for (int i = 0; i < (int)visits.size(); i++) {
        inWindow[visits[i]]++;                   // the new visit enters
        if (i >= window) {
            int old = visits[i - window];        // the oldest visit leaves
            if (--inWindow[old] == 0) inWindow.erase(old);   // drop keys at 0
        }
