using System;
using System.Collections.Generic;

class Program {
    // Time: O(N), each visit is added once and removed once. Space: O(window).
    static List<int> UniquePerWindow(int[] visits, int window) {
        Dictionary<int, int> inWindow = new Dictionary<int, int>();   // user id -> visits inside the window
        List<int> result = new List<int>();
        for (int i = 0; i < visits.Length; i++) {
            int c;
            inWindow.TryGetValue(visits[i], out c);
            inWindow[visits[i]] = c + 1;                 // the new visit enters
            if (i >= window) {
                int old = visits[i - window];            // the oldest visit leaves
                inWindow[old]--;
                if (inWindow[old] == 0) inWindow.Remove(old);   // drop keys at 0
            }
            if (i >= window - 1) result.Add(inWindow.Count);    // map size = unique users
        }
        return result;
    }

    static void Main() {
        int[] visits = { 7, 7, 8, 7, 9, 9, 9, 9 };
        int window = 4;
        Console.WriteLine("visits (user ids) = [" + string.Join(", ", visits) + "], window = " + window);
        Console.WriteLine("unique visitors per window: [" + string.Join(", ", UniquePerWindow(visits, window)) + "]");
    }
}
